PROVIDER_PATHS = {'strategy': ('tools/high_level_gameplay_flow/strategy_steps.py', 'tools/high_level_gameplay_flow/compiler_strategy_steps.py'), 'command': ('tools/high_level_main_flows/command_message_steps.py', 'tools/high_level_main_flows/compiler_command_message_steps.py'), 'message': ('tools/high_level_gameplay_flow/message_scene_steps.py', 'tools/high_level_gameplay_flow/compiler_message_scene_steps.py')}
COMMAND_PATH = 'tools/high_level_main_flows/business_commands.py'
MAIN_PATH = 'tools/high_level_main_flows/business_main.py'

def _literal(tree,name):
    rows=[node for node in tree.body if isinstance(node,ast.Assign)
        and len(node.targets)==1 and isinstance(node.targets[0],ast.Name)
        and node.targets[0].id==name]
    if len(rows)!=1:raise ValueError('one exact registered constant required: '+name)
    return ast.literal_eval(rows[0].value)


def _functions(tree,names):
    rows=[node for node in tree.body if isinstance(node,ast.FunctionDef) and node.name in names]
    if len(rows)!=len(names) or {node.name for node in rows}!=set(names):
        raise ValueError('every exact complete source utility required')
    return rows


def admit_city_command_source(source,business_sources,provider_sources,registry_sources):
    """Only this batch's exact source/inverse/CodeType preparation, not a game."""
    dump=lambda node:ast.dump(node,include_attributes=False)
    tree=ast.parse(source)
    if dump(tree)!=EXPECTED_MODULE_AST:
        raise ValueError('complete admitted city-command module differs')
    if set(provider_sources)!=set(PROVIDER_PATHS) or set(registry_sources)!=set(PROVIDER_PATHS):
        raise ValueError('all three explicit existing provider/registry source pairs required')
    parsed_providers={}
    registries={}
    for group,text in provider_sources.items():
        actual=ast.parse(text)
        registry=ast.parse(registry_sources[group])
        if dump(actual)!=_literal(registry,'EXPECTED_MODULE_AST'):
            raise ValueError('actual existing provider no longer matches its exact registry: '+group)
        parsed_providers[group]=actual
        registries[group]=registry
    if set(business_sources)!={COMMAND_PATH,MAIN_PATH}:
        raise ValueError('the complete original Main and commands modules are required')
    expected=_literal(registries['command'],'EXPECTED_OWNER_ASTS')
    commands=ast.parse(business_sources[COMMAND_PATH])
    command_nodes={node.name:node for node in commands.body if isinstance(node,ast.FunctionDef)}
    names=_literal(tree,'PARENT_NAMES')
    for name in names:
        if name not in command_nodes or dump(command_nodes[name])!=expected['commands'][name]:
            raise ValueError('complete registered city-command parent source differs: '+name)
    main=ast.parse(business_sources[MAIN_PATH])
    original=_functions(main,('initialize_campaign_map_fields',))[0]
    if dump(original)!=expected['main'][original.name]:
        raise ValueError('complete actual original Main434 parent differs')
    pairs=[tuple(ast.literal_eval(value) for value in node.args[2:])
        for node in ast.walk(original) if isinstance(node,ast.Call)
        and isinstance(node.func,ast.Name) and node.func.id=='_campaign_call_fields']
    if pairs!=[(0xDF6E,0x8E4)]:raise ValueError('only real Main434 DF6E/8E4 CALL admitted')
    command=parsed_providers['command']
    base_namespace=dict(ast=ast,copy=copy)
    for name in ('VIEW_SPECS','CHILD_ADAPTERS','LOCAL_IMPORT_ADAPTERS'):
        base_namespace[name]=_literal(command,name)
    utilities=_functions(command,('_dump','_cooperative_tree'))
    exec(compile(ast.Module(body=utilities,type_ignores=[]),'<existing command whole-source inverse>','exec'),base_namespace)
    namespace=dict(ast=ast,copy=copy,_dump=dump,
        EXPECTED_OWNER_ASTS=expected,PARENT_NAMES=names,
        _base_cooperative_tree=base_namespace['_cooperative_tree'])
    utilities=_functions(tree,('_city_command_module',))
    exec(compile(ast.Module(body=utilities,type_ignores=[]),'<new command whole-module inverse>','exec'),namespace)
    derived=namespace['_city_command_module'](commands)
    plain_code=compile(commands,'<complete original city-command module>','exec',dont_inherit=True)
    derived_code=compile(derived,'<complete cooperative city-command module>','exec',dont_inherit=True)
    for name in names:
        plain=[code for code in plain_code.co_consts if type(code)is types.CodeType and code.co_name==name]
        changed=[code for code in derived_code.co_consts if type(code)is types.CodeType and code.co_name==name]
        if len(plain)!=1 or len(changed)!=1 or plain[0].co_flags&32 or not changed[0].co_flags&32:
            raise ValueError('one complete original/derived generator CodeType required: '+name)
    # The actual first-force tail must skip30960 initialization. The category
    # branch likewise keeps the original second-force prefixFalse operand.
    derived_nodes={node.name:node for node in derived.body if isinstance(node,ast.FunctionDef)}
    force_args={}
    for name in names:
        calls=[node for node in ast.walk(derived_nodes[name]) if isinstance(node,ast.Call)
            and isinstance(node.func,ast.Name) and node.func.id in (
                '_diplomacy_first_force_turn_fields','_diplomacy_second_force_turn_fields')]
        if len(calls)!=1 or calls[0].keywords or len(calls[0].args)!=3:
            raise ValueError('one exact existing force tail required in each parent')
        force_args[calls[0].func.id]=ast.literal_eval(calls[0].args[2])
    if force_args!={'_diplomacy_first_force_turn_fields':False,'_diplomacy_second_force_turn_fields':False}:
        raise ValueError('real first/second no-prefix force tails must remain False')
    return dict(confidence='confirmed_source_only',main=0x434,outer_return=0x3CE,
        actual_child=(0xDF6E,0x8E4),new_complete_parent_views=2,
        new_propagated_JMP060C_tails=2,reused_complete_strategy_force_views=3,
        original_FN_and_wholemodule_inverses=True,existing_private_views_mutated=False,
        existing_shared_message_instance=True,provider_registry_pairs=3,
        new_algorithm_bodies=0,new_CALL_slots=0,new_wait_types=0,
        unproven_30960_DFD8_alias_added=False,normal_DECL_changed=False,
        factory_cold_install_pins='Root owns one434 provider change;54targets unchanged',
        formal_credit=0,strict_pending_unchanged=46004,game=False,fixture=False,
        normal_API=False,native=False,hash=False,old_replay=False,public_modified=False)
